local KTool = CS.Engine.Lib.KTool

---@class NewChapterSummary
---@field TextTitle                     	UnityEngine.UI.Text
---@field bg                            	UnityEngine.RectTransform
---@field ChapterSummaryPopup           	UGUI.Effects.UIEffectCapturedImage
---@field FontStyleWithIconButton2      	UnityEngine.UI.Button
---@field FontStyleWithIconButton       	UnityEngine.UI.Button
---@field TextContent                   	UnityEngine.UI.Text
local NewChapterSummary = Class('NewChapterSummary')
local cs_coroutine = require 'XLua.cs_coroutine'
--"\u00A0"
local NonBreakingSpace = utf8.char(160)

local ChapterUtils = import('Game.Chapter.ChapterUtils')

function NewChapterSummary:__init()
    --
    self.onClose = nil
    self.onConfirm = nil
end

function NewChapterSummary:__delete()
    --
    self.onClose = nil
    self.onConfirm = nil
end

function NewChapterSummary:Awake()
end

function NewChapterSummary:Start()
    SetButtonAction(self.FontStyleWithIconButton, function()
        KTool.SetActive(self.controller.gameObject, false)
        if self.onClose ~= nil then
            self.onClose()
        end
        self:Dispose()
        self:Delete()
    end)

    SetButtonAction(self.FontStyleWithIconButton2, function()
        KTool.SetActive(self.controller.gameObject, false)
        if self.onConfirm ~= nil then
            self.onConfirm()
        end
        self:Dispose()
        self:Delete()
    end)
    
    SetButtonAction(self.bg, function()
        KTool.SetActive(self.controller.gameObject, false)
        if self.onClose ~= nil then
            self.onClose()
        end
        self:Dispose()
        self:Delete()
    end)
end

---@param generalVo ChapterGeneralVo
function NewChapterSummary:Show(generalVo, onClose, onConfirm)
    if not KTool.IsActiveInHierarchy(self.controller.gameObject) then
        KTool.SetActive(self.controller.gameObject, true)
    end
    self.ChapterSummaryPopup:Capture()
    local content = ChapterUtils.ReplaceStr(generalVo.desc, "\\n", "\n")
    ---不清楚当时为什么要将空格替换成这种带编码的空格  但是英文会分割单词 所以先屏蔽  ---中文混合的时候 会有问题
    if CS.Engine.I18N.I18NModule.Lang ~= "en_US" and CS.Engine.I18N.I18NModule.Lang ~= "en_UK" then
        content = ChapterUtils.ReplaceStr(content, " ", NonBreakingSpace)
    end
    self.TextContent.text = content

    self:RemoveResetCo()
    self.resetCo = cs_coroutine.start(function()
        coroutine.yield(CS.UnityEngine.Yielders.EndOfFrame)
        if self.TextContent.preferredHeight >= 290  then
            self.VertContent.pivot = Vector2.New(0,1)
            self.VertContent.anchoredPosition.y = 0
        else
            self.VertContent.pivot = Vector2.New(0.5,0.5)
        end
    end)

--[[    if self.TextContent.preferredHeight >= 290  then
        self.VertContent.pivot = Vector2.New(0,1)
        self.VertContent.anchoredPosition.y = 0
    else
        self.VertContent.pivot = Vector2.New(0.5,0.5)
    end]]

    if not KTool.IsActiveInHierarchy(self.TextTitle.gameObject) then
        KTool.SetActive(self.TextTitle, true)
    end
    self.TextTitle.text = generalVo.title
    self.onClose = onClose
    self.onConfirm = onConfirm
end

function NewChapterSummary:Dispose()
    self.ChapterSummaryPopup:Release()
    self:RemoveResetCo()
end

function NewChapterSummary:RemoveResetCo()
    if not isNull(self.resetCo) then
        cs_coroutine.stop(self.resetCo)
        self.resetCo = nil
    end
end

function NewChapterSummary:OnDestroy()
    self:RemoveResetCo()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return NewChapterSummary